    "text": "export interface Hotspot {\n  id: string;\n  name: string;\n  description: string;\n  position: { x: number; y: number; z: number };\n  normal?: { x: number; y: number; z: number };\n  value?: number;\n  isCustom?: boolean;\n}\n\nexport interface Organ {\n  id: string;\n  name: string;\n  description: string;\n  function: string;\n  image: string;\n  model: string;\n  hotspots?: Hotspot[];\n  clickableMeshes?: string[];\n}\n\nexport interface OrganScreenshot {\n  id: string;\n  organId: string;\n  organName: string;\n  imageDataUrl: string;\n  capturedAt: string;\n  focusedPart?: string;\n  camera: {\n    position: { x: number; y: number; z: number };\n    target: { x: number; y: number; z: number };\n  };\n}\n\r",
